function lotAllocationFields(initial){var lots=initial.validated&&initial.validated.divisionIntoLots&&Array.isArray(initial.validated.lots)?initial.validated.lots:[];if(!lots.length)return '<p class="info"><strong>Lote único:</strong> el PBL total corresponde al contrato completo.</p>';var base=Math.floor(100/lots.length),remaining=100-base*lots.length;return '<div class="info"><strong>Distribución porcentual del PBL entre lotes</strong><p>Propuesta inicial: reparto igualitario porque todavía no constan unidades o cargas económicas diferenciadas. Puede corregir únicamente los porcentajes; los importes se calculan automáticamente.</p>'+lots.map(function(lot,index){var percentage=base+(index===lots.length-1?remaining:0);return '<label>'+esc(lot.name)+' · porcentaje del PBL total</label><input class="lb108LotPercent" data-index="'+index+'" data-id="'+esc(lot.id)+'" data-name="'+esc(lot.name)+'" type="number" min="0" max="100" step="1" value="'+percentage+'"><div class="muted lb108LotAmount">Importe calculado: pendiente de indicar el PBL total</div>';}).join('')+'</div>';}
