function legal(items){return '<details><summary>Fundamento jurídico, artículo y texto aplicable</summary>'+items.map(function(b){return '<div class="info"><strong>'+esc(b.norm)+' · artículo '+esc(b.article)+', apartado '+esc(b.paragraph)+'</strong><br>«'+esc(b.relevantOfficialExcerpt)+'»<br><a href="'+esc(b.officialUrl)+'" target="_blank" rel="noopener noreferrer">Consultar texto oficial BOE</a></div>';}).join("")+'</details>';}
async function json(url,options){if(url==="/api/lb108/economic-starting-point"&&options&&options.body&&document.querySelector(".lb108Method")){var payload=JSON.parse(options.body),flow=readAnswers().__lb108||{},guided=document.getElementById("lb108GuidedCostStudy");payload.budgetConstraint=flow.budgetConstraint;payload.valuationAssistance=flow.valuationAssistance;if(flow.budgetConstraint==="NOT_PRESET")delete payload.grossCreditLimitCents;payload.valuationMethodologies=[].slice.call(document.querySelectorAll(".lb108Method:checked")).map(function(x){return x.value;});payload.valuationSupports=[].slice.call(document.querySelectorAll(".lb108Support:checked")).map(function(x){return x.value;});payload.otherValuationSource=String((document.getElementById("lb108OtherValuationSource")||{}).value||"").trim();payload.supportingDocuments=valuationDocuments;if(guided&&guided.dataset.applied==="true")payload.guidedServiceCostStudy=readGuidedServiceCostStudy();options=Object.assign({},options,{body:JSON.stringify(payload)});}var r=await fetch(url,Object.assign({credentials:"same-origin",headers:{"content-type":"application/json"}},options||{}));var body=await r.json().catch(function(){return {};});if(!r.ok)throw new Error(body.error||"No se pudo completar la operación.");return body;}
