async function uploadValuationDocuments(id){var files=[].slice.call(document.getElementById("lb108Documents").files||[]),out=[];if(!files.length)throw new Error("Incorpore al menos un documento justificativo.");for(var i=0;i<files.length;i++){var f=files[i],r=await fetch("/api/lb108/cases/"+encodeURIComponent(id)+"/valuation-documents",{method:"PUT",credentials:"same-origin",headers:{"content-type":f.type||"application/octet-stream","x-file-name":encodeURIComponent(f.name)},body:f});var b=await r.json().catch(function(){return{};});if(!r.ok)throw new Error(b.error||"No se pudo incorporar "+f.name);out.push(b);}valuationDocuments=out;return out;}
async function validateEvidenceRaw(id,path,value){var root="/api/adaptive/cases/"+encodeURIComponent(id)+"/universal-evidence";await json(root,{method:"PUT",body:JSON.stringify({fieldPath:path,value:value,sourceId:"ui:lb108:economic-starting-point",note:"Dato o cálculo económico revisado y confirmado expresamente por la persona responsable"})});await json(root+"/validate",{method:"POST",body:JSON.stringify({fieldPath:path})});}
