function methodologyOptionsV2(proposed,assisted){return["COST_STUDY","QUOTES_OR_CATALOGUES","PRIOR_CONTRACTS","MARKET_CONSULTATION","OTHER_JUSTIFIED"].map(function(value){return '<label class="card" style="display:block;margin:.55rem 0;padding:.75rem"><input class="lb108Method" type="checkbox" value="'+value+'" style="width:auto" '+(assisted&&value===proposed?'checked':'')+'> <strong>'+methodLabel(value)+'</strong>'+(assisted&&value===proposed?' <span class="muted">· Propuesta del asistente</span>':'')+'<br><span class="muted">'+METHOD_DESCRIPTIONS[value]+'</span></label>';}).join("");}
