function supportSelectionError(methods,chosen){for(var i=0;i<methods.length;i++){var method=methods[i],requirement=METHOD_REQUIREMENTS[method],missing=requirement.all.filter(function(value){return chosen.indexOf(value)<0;});if(missing.length)return methodLabel(method)+" requiere seleccionar: "+missing.map(function(value){return SUPPORT_DETAILS[value].label;}).join(", ")+".";if(requirement.any&&!requirement.any.some(function(value){return chosen.indexOf(value)>=0;}))return methodLabel(method)+" requiere al menos uno de estos apoyos principales: "+requirement.any.map(function(value){return SUPPORT_DETAILS[value].label;}).join(" o ")+".";}return"";}
function enhanceValuationEvidenceV2(){var a=readAnswers(),id=caseId(),button=document.getElementById("lb108Calculate");if(!button||button.dataset.valuationEnhancedV2)return;button.dataset.valuationEnhancedV2="true";var proposed=proposedMethod(a),assisted=(a.__lb108||{}).valuationAssistance==="ASSISTED",box=document.createElement("div");box.className="info";box.innerHTML='<h3>Metodologías de valoración</h3><p><strong>Puede seleccionar una o varias.</strong> '+(assisted?'El asistente marca una propuesta inicial y explica qué debe acreditarse. Revísela y conserve únicamente lo que realmente vaya a aplicar.':'Seleccione las metodologías utilizadas en su documentación; ninguna aparece premarcada para evitar atribuirle un método que no haya aplicado.')+'</p><div id="lb108Methods">'+methodologyOptionsV2(proposed,assisted)+'</div><h3>Apoyos que sostienen las metodologías</h3><p class="muted">Marque los datos y documentos utilizados realmente. Los obligatorios aparecen identificados; cuando se indiquen alternativas, basta con seleccionar una de ellas.</p><div id="lb108Supports"></div><label><strong>Documentos justificativos</strong> (máximo 10 MB por archivo)</label><input id="lb108Documents" type="file" multiple><p class="muted">Los documentos se incorporarán físicamente al expediente y quedarán identificados por su huella SHA-256.</p>';button.parentNode.insertBefore(box,button);var supports=document.getElementById("lb108Supports");function redraw(){var checked={};[].slice.call(document.querySelectorAll(".lb108Support:checked")).forEach(function(x){checked[x.value]=true;});var methods=selectedMethods();supports.innerHTML=methods.length?supportCardsV2(methods):'<p class="warning">Seleccione al menos una metodología para mostrar sus apoyos compatibles.</p>';[].slice.call(document.querySelectorAll(".lb108Support")).forEach(function(x){x.checked=!!checked[x.value];});} [].slice.call(document.querySelectorAll(".lb108Method")).forEach(function(x){x.onchange=redraw;});redraw();var original=button.onclick;button.onclick=async function(event){event.preventDefault();event.stopImmediatePropagation();var status=document.getElementById("lb108Status");try{var methods=selectedMethods(),chosen=[].slice.call(document.querySelectorAll(".lb108Support:checked")).map(function(x){return x.value;});if(!methods.length)throw new Error("Seleccione al menos una metodología de valoración.");var supportError=supportSelectionError(methods,chosen);if(supportError)throw new Error(supportError);button.disabled=true;status.textContent="Incorporando y verificando documentos…";var documents=await uploadValuationDocuments(id),evidence=document.getElementById("lb108Evidence"),base=evidence.value.trim();if(!base)throw new Error("Describa la fuente, fecha, referencia, comparabilidad y ajustes de la valoración.");evidence.value=base+"\nMetodologías: "+methods.map(methodLabel).join(", ")+". Apoyos: "+chosen.map(function(x){return SUPPORT_DETAILS[x].label;}).join(", ")+". Documentos: "+documents.map(function(x){return x.fileName+" [SHA-256 "+x.sha256+"]";}).join("; ");button.disabled=false;await original.call(button,event);}catch(e){button.disabled=false;status.textContent=e.message;status.className="warning";}};}
