function guidedCostRow(){return '<div class="card lb108CostLine" style="margin:.6rem 0;padding:.75rem"><label>Categoría</label><select class="lb108CostCategory"><option value="LABOUR">Personal</option><option value="MATERIAL">Materiales</option><option value="EQUIPMENT">Equipos, licencias o medios</option><option value="OTHER_DIRECT">Otro coste directo</option></select><label>Concepto</label><input class="lb108CostConcept" placeholder="Ej.: técnico especialista"><label>Unidad de cálculo</label><input class="lb108CostUnit" placeholder="Ej.: hora, mes, visita o unidad"><label>Cantidad</label><input class="lb108CostQuantity" type="number" min="0" step="0.01"><label>Precio unitario sin IVA (€)</label><input class="lb108CostUnitPrice" type="number" min="0" step="0.01"><label>Fuente del precio</label><input class="lb108CostSource" placeholder="Convenio, tarifa, catálogo, oferta o contrato comparable, con fecha"><p class="muted lb108CostLineTotal">Total del concepto: pendiente</p><button class="secondary lb108RemoveCost" type="button">Eliminar concepto</button></div>';}
function readGuidedServiceCostStudy(){var lines=[].slice.call(document.querySelectorAll(".lb108CostLine")).map(function(row){return{category:row.querySelector(".lb108CostCategory").value,concept:row.querySelector(".lb108CostConcept").value.trim(),unit:row.querySelector(".lb108CostUnit").value.trim(),quantity:Number(row.querySelector(".lb108CostQuantity").value),unitCostExVatCents:Math.round(Number(row.querySelector(".lb108CostUnitPrice").value)*100),source:row.querySelector(".lb108CostSource").value.trim()};});return{lines:lines,indirectRatePercent:Number(document.getElementById("lb108GuidedIndirectRate").value),profitRatePercent:Number(document.getElementById("lb108GuidedProfitRate").value)};}
function guidedCostTotals(){var box=document.getElementById("lb108GuidedCostStudy"),direct=0;[].slice.call(box.querySelectorAll(".lb108CostLine")).forEach(function(row){var quantity=Number(row.querySelector(".lb108CostQuantity").value||0),price=Math.round(Number(row.querySelector(".lb108CostUnitPrice").value||0)*100),total=Math.round(quantity*price);direct+=total;row.querySelector(".lb108CostLineTotal").textContent="Total del concepto sin IVA: "+money(total);});var indirectRate=Number(document.getElementById("lb108GuidedIndirectRate").value||0),profitRate=Number(document.getElementById("lb108GuidedProfitRate").value||0),vatRate=Number((document.getElementById("lb108Vat")||{}).value||0),indirect=Math.round(direct*indirectRate/100),profit=Math.round((direct+indirect)*profitRate/100),base=direct+indirect+profit,vat=Math.round(base*vatRate/100);return{direct:direct,indirect:indirect,profit:profit,base:base,vat:vat,gross:base+vat};}
function updateGuidedServiceCost(){var box=document.getElementById("lb108GuidedCostStudy");if(!box)return;box.dataset.applied="false";var totals=guidedCostTotals();document.getElementById("lb108GuidedCostSummary").innerHTML='<strong>Resultado provisional</strong><br>Costes directos: '+money(totals.direct)+'<br>Costes indirectos: '+money(totals.indirect)+'<br>Beneficio: '+money(totals.profit)+'<br>PBL sin IVA: '+money(totals.base)+'<br>IVA: '+money(totals.vat)+'<br><strong>PBL con IVA: '+money(totals.gross)+'</strong><br><span class="muted">Este resultado todavía no ha sustituido el PBL del formulario.</span>';}
function applyGuidedServiceCost(){var box=document.getElementById("lb108GuidedCostStudy"),study=readGuidedServiceCostStudy();for(var i=0;i<study.lines.length;i++){var line=study.lines[i];if(!line.concept||!line.unit||!line.source||!Number.isFinite(line.quantity)||line.quantity<=0||!Number.isFinite(line.unitCostExVatCents)||line.unitCostExVatCents<=0)throw new Error("Complete concepto, unidad, cantidad, precio y fuente en todas las líneas antes de aplicar el cálculo.");}var totals=guidedCostTotals();if(totals.gross<=0)throw new Error("El estudio de costes debe producir un PBL superior a cero.");var budget=document.getElementById("lb108ContractBudget");budget.value=(totals.gross/100).toFixed(2);var total=totals.base||1,dp=totals.direct*100/total,ip=totals.indirect*100/total;document.getElementById("lb108DirectPercent").value=String(dp);document.getElementById("lb108IndirectPercent").value=String(ip);document.getElementById("lb108OtherPercent").value=String(100-dp-ip);box.dataset.applied="true";updateAutomaticAmounts();document.getElementById("lb108GuidedCostSummary").insertAdjacentHTML("beforeend",'<br><strong style="color:#176b46">Cálculo aplicado al PBL. Puede modificarlo manualmente; en ese caso, el estudio dejará de considerarse aplicado.</strong>');}
function bindGuidedCostRows(){var box=document.getElementById("lb108GuidedCostStudy");if(!box)return;[].slice.call(box.querySelectorAll("input,select")).forEach(function(el){el.oninput=updateGuidedServiceCost;});[].slice.call(box.querySelectorAll(".lb108RemoveCost")).forEach(function(button){button.onclick=function(){if(box.querySelectorAll(".lb108CostLine").length===1){document.getElementById("lb108Status").textContent="El estudio debe conservar al menos un concepto.";return;}button.closest(".lb108CostLine").remove();bindGuidedCostRows();updateGuidedServiceCost();};});}
