var r=s.result,b=r.budget,v=r.estimatedValue;panel.innerHTML='<div class="card"><h2>Revise el cálculo económico</h2><p><strong>Crédito único disponible para el contrato, con IVA:</strong> '+money(b.availableCreditVatIncludedCents)+'</p><p><strong>PBL total sin IVA:</strong> '+money(b.baseTenderBudgetExVatCents)+'</p><p><strong>Desglose:</strong> costes directos '+b.costBreakdown.directPercent+' % = '+money(b.costBreakdown.directCostsExVatCents)+'; costes indirectos '+b.costBreakdown.indirectPercent+' % = '+money(b.costBreakdown.indirectCostsExVatCents)+'; beneficio industrial '+b.costBreakdown.otherPercent+' % = '+money(b.costBreakdown.otherCostsExVatCents)+'.</p><p><strong>IVA:</strong> '+money(b.vatAmountCents)+'</p><p><strong>PBL total del contrato con IVA:</strong> '+money(b.baseTenderBudgetVatIncludedCents)+'</p>'+(b.lotPblAllocations.length?'<h3>Distribución del PBL entre lotes</h3><ul>'+b.lotPblAllocations.map(function(x){return '<li>'+esc(x.lot)+': '+x.percentage+' % = '+money(x.pblVatIncludedCents)+'</li>';}).join('')+'</ul><p class="muted">Estos importes distribuyen el PBL; no son créditos máximos independientes.</p>':'')+'<p><strong>Valor estimado global de todos los lotes, sin IVA:</strong> '+money(v.legalEstimatedValueCents)+'</p><p class="muted">'+esc(v.calculationMethod)+'</p>'+r.warnings.map(function(w){return '<p class="warning">'+esc(w)+'</p>';}).join("")+'<h3>Procedimiento que debe estudiarse después</h3><p><strong>'+esc(r.procedure.label)+'</strong><br>'+esc(r.procedure.reasoning)+'</p><ul>'+r.procedure.conditions.map(function(c){return '<li>'+esc(c)+'</li>';}).join("")+'</ul>'+legal(r.legalBasis)+'<button id="lb108Confirm" type="button">Confirmar magnitudes económicas</button> <button id="lb108Recalculate" type="button" class="secondary">Corregir datos</button><p id="lb108Status" class="muted"></p></div>';
